### 7. API Endpoints — Server Program.cs

Add these BEFORE `app.Run();` in server `Program.cs`:
```csharp
// Shipment API endpoints
var shipments = app.MapGroup("api/shipments").RequireAuthorization();

shipments.MapGet("", async (ShipmentServerService svc) => await svc.GetAllShipmentsAsync());

shipments.MapGet("{id:int}", async (int id, ShipmentServerService svc) =>
{
    var s = await svc.GetShipmentAsync(id);
    return s is null ? Results.NotFound() : Results.Ok(s);
});

shipments.MapGet("track/{trackingNumber}", async (string trackingNumber, ShipmentServerService svc) =>
    await svc.TrackShipmentAsync(trackingNumber)).AllowAnonymous();

shipments.MapPost("", async (ShipmentDto dto, ShipmentServerService svc) =>
{
    var created = await svc.CreateShipmentAsync(dto);
    return Results.Created($"api/shipments/{created.Id}", created);
});

shipments.MapPut("{id:int}", async (int id, ShipmentDto dto, ShipmentServerService svc) =>
{
    dto.Id = id;
    var updated = await svc.UpdateShipmentAsync(dto);
    return Results.Ok(updated);
});

shipments.MapDelete("{id:int}", async (int id, ShipmentServerService svc) =>
{
    await svc.DeleteShipmentAsync(id);
    return Results.NoContent();
});
```

