    private List<ShipmentDto> shipments = [];
    private bool isLoading = true;
    private string filterText = string.Empty;

    private bool showForm;
    private ShipmentDto editingShipment = new();
    private bool isSaving;
    private string? formError;

    private bool showDeleteConfirm;
    private ShipmentDto? deletingShipment;

    private IEnumerable<ShipmentDto> FilteredShipments => string.IsNullOrWhiteSpace(filterText)
        ? shipments
        : shipments.Where(s =>
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.RecipientName.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Status.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowCreateForm()
    {
        editingShipment = new ShipmentDto { Status = "Pending", TrackingNumber = GenerateTrackingNumber() };
        formError = null;
        showForm = true;
    }

    private void EditShipment(ShipmentDto shipment)
    {
        editingShipment = new ShipmentDto
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
            CreatedAt = shipment.CreatedAt,
            EstimatedDelivery = shipment.EstimatedDelivery,
            ActualDelivery = shipment.ActualDelivery,
            RecipientName = shipment.RecipientName,
            RecipientEmail = shipment.RecipientEmail,
            Notes = shipment.Notes
        };
        formError = null;
        showForm = true;
    }

    private void CloseForm() => showForm = false;

    private async Task SaveShipment()
    {
        if (string.IsNullOrWhiteSpace(editingShipment.TrackingNumber) ||
            string.IsNullOrWhiteSpace(editingShipment.Origin) ||
            string.IsNullOrWhiteSpace(editingShipment.Destination) ||
            string.IsNullOrWhiteSpace(editingShipment.RecipientName))
        {
            formError = "Please fill in all required fields.";
            return;
        }

        isSaving = true;
        formError = null;
        try
        {
            if (editingShipment.Id == 0)
                await ShipmentService.CreateShipmentAsync(editingShipment);
            else
                await ShipmentService.UpdateShipmentAsync(editingShipment);

            showForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            formError = $"Failed to save: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void ConfirmDelete(ShipmentDto shipment)
    {
        deletingShipment = shipment;
        showDeleteConfirm = true;
    }

    private async Task DeleteShipment()
    {
        if (deletingShipment is not null)
        {
            await ShipmentService.DeleteShipmentAsync(deletingShipment.Id);
            showDeleteConfirm = false;
            deletingShipment = null;
            await LoadShipments();
        }
    }

    private static string GenerateTrackingNumber()
        => $"ST-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(1000, 9999)}";

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-info",
        "PickedUp" => "bg-secondary",
        "Exception" => "bg-danger",
        _ => "bg-warning text-dark"
    };
}
