namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string RecipientEmail { get; set; } = string.Empty;
    public string? Notes { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}

namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string RecipientEmail { get; set; } = string.Empty;
    public string? Notes { get; set; }
}

public class TrackingResult
{
    public bool Found { get; set; }
    public ShipmentDto? Shipment { get; set; }
    public string? ErrorMessage { get; set; }
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetAllShipmentsAsync();
    Task<ShipmentDto?> GetShipmentAsync(int id);
    Task<TrackingResult> TrackShipmentAsync(string trackingNumber);
    Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment);
    Task<ShipmentDto> UpdateShipmentAsync(ShipmentDto shipment);
    Task DeleteShipmentAsync(int id);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
        => await http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
        => await http.GetFromJsonAsync<ShipmentDto>($"api/shipments/{id}");

    public async Task<TrackingResult> TrackShipmentAsync(string trackingNumber)
        => await http.GetFromJsonAsync<TrackingResult>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}") ?? new TrackingResult { Found = false, ErrorMessage = "Service unavailable" };

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var response = await http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDto>() ?? shipment;
    }

    public async Task<ShipmentDto> UpdateShipmentAsync(ShipmentDto shipment)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{shipment.Id}", shipment);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDto>() ?? shipment;
    }

    public async Task DeleteShipmentAsync(int id)
    {
        var response = await http.DeleteAsync($"api/shipments/{id}");
        response.EnsureSuccessStatusCode();
    }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
        => await db.Shipments.OrderByDescending(s => s.CreatedAt).Select(s => ToDto(s)).ToListAsync();

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        var s = await db.Shipments.FindAsync(id);
        return s is null ? null : ToDto(s);
    }

    public async Task<TrackingResult> TrackShipmentAsync(string trackingNumber)
    {
        var s = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        if (s is null)
            return new TrackingResult { Found = false, ErrorMessage = "No shipment found with that tracking number." };
        return new TrackingResult { Found = true, Shipment = ToDto(s) };
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var shipment = new Shipment
        {
            TrackingNumber = dto.TrackingNumber,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = Enum.Parse<ShipmentStatus>(dto.Status),
            CreatedAt = DateTime.UtcNow,
            EstimatedDelivery = dto.EstimatedDelivery,
            RecipientName = dto.RecipientName,
            RecipientEmail = dto.RecipientEmail,
            Notes = dto.Notes
        };
        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task<ShipmentDto> UpdateShipmentAsync(ShipmentDto dto)
    {
        var shipment = await db.Shipments.FindAsync(dto.Id) ?? throw new KeyNotFoundException($"Shipment {dto.Id} not found");
        shipment.Origin = dto.Origin;
        shipment.Destination = dto.Destination;
        shipment.Status = Enum.Parse<ShipmentStatus>(dto.Status);
        shipment.EstimatedDelivery = dto.EstimatedDelivery;
        shipment.ActualDelivery = dto.ActualDelivery;
        shipment.RecipientName = dto.RecipientName;
        shipment.RecipientEmail = dto.RecipientEmail;
        shipment.Notes = dto.Notes;
        await db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task DeleteShipmentAsync(int id)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is not null)
        {
            db.Shipments.Remove(shipment);
            await db.SaveChangesAsync();
        }
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        RecipientName = s.RecipientName,
        RecipientEmail = s.RecipientEmail,
        Notes = s.Notes
    };
}

@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments - Dispatcher Dashboard</PageTitle>

<h1>Shipments</h1>

<div class="d-flex justify-content-between align-items-center mb-3">
    <div class="input-group" style="max-width: 300px;">
        <input type="text" class="form-control" placeholder="Filter..." @bind="filterText" @bind:event="oninput" />
        @if (!string.IsNullOrEmpty(filterText))
        {
            <button class="btn btn-outline-secondary" @onclick="() => filterText = string.Empty">✕</button>
        }
    </div>
    <button class="btn btn-primary" @onclick="ShowCreateForm">
        + New Shipment
    </button>
</div>

@if (isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Recipient</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.RecipientName</td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            <button class="btn btn-sm btn-outline-primary me-1" @onclick="() => EditShipment(s)">Edit</button>
                            <button class="btn btn-sm btn-outline-danger" @onclick="() => ConfirmDelete(s)">Delete</button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (!FilteredShipments.Any())
    {
        <p class="text-muted text-center">No shipments found.</p>
    }
}

@if (showForm)
{
    <div class="modal d-block" tabindex="-1" style="background: rgba(0,0,0,0.5)">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">@(editingShipment.Id == 0 ? "New Shipment" : "Edit Shipment")</h5>
                    <button type="button" class="btn-close" @onclick="CloseForm"></button>
                </div>
                <div class="modal-body">
                    @if (!string.IsNullOrEmpty(formError))
                    {
                        <div class="alert alert-danger">@formError</div>
                    }
                    <div class="mb-3">
                        <label class="form-label">Tracking Number</label>
                        <input class="form-control" @bind="editingShipment.TrackingNumber" disabled="@(editingShipment.Id != 0)" />
                    </div>
                    <div class="row mb-3">
                        <div class="col">
                            <label class="form-label">Origin</label>
                            <input class="form-control" @bind="editingShipment.Origin" />
                        </div>
                        <div class="col">
                            <label class="form-label">Destination</label>
                            <input class="form-control" @bind="editingShipment.Destination" />
                        </div>
                    </div>
                    <div class="row mb-3">
                        <div class="col">
                            <label class="form-label">Recipient Name</label>
                            <input class="form-control" @bind="editingShipment.RecipientName" />
                        </div>
                        <div class="col">
                            <label class="form-label">Recipient Email</label>
                            <input class="form-control" type="email" @bind="editingShipment.RecipientEmail" />
                        </div>
                    </div>
                    <div class="row mb-3">
                        <div class="col">
                            <label class="form-label">Status</label>
                            <select class="form-select" @bind="editingShipment.Status">
                                <option value="Pending">Pending</option>
                                <option value="PickedUp">Picked Up</option>
                                <option value="InTransit">In Transit</option>
                                <option value="OutForDelivery">Out for Delivery</option>
                                <option value="Delivered">Delivered</option>
                                <option value="Exception">Exception</option>
                            </select>
                        </div>
                        <div class="col">
                            <label class="form-label">Estimated Delivery</label>
                            <input class="form-control" type="date" @bind="editingShipment.EstimatedDelivery" />
                        </div>
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Notes</label>
                        <textarea class="form-control" rows="2" @bind="editingShipment.Notes"></textarea>
                    </div>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CloseForm">Cancel</button>
                    <button class="btn btn-primary" @onclick="SaveShipment" disabled="@isSaving">
                        @if (isSaving)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Save
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@if (showDeleteConfirm && deletingShipment is not null)
{
    <div class="modal d-block" tabindex="-1" style="background: rgba(0,0,0,0.5)">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Confirm Delete</h5>
                    <button type="button" class="btn-close" @onclick="() => showDeleteConfirm = false"></button>
                </div>
                <div class="modal-body">
                    <p>Delete shipment <strong>@deletingShipment.TrackingNumber</strong>?</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="() => showDeleteConfirm = false">Cancel</button>
                    <button class="btn btn-danger" @onclick="DeleteShipment">Delete</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool isLoading = true;
    private string filterText = string.Empty;

    private bool showForm;
    private ShipmentDto editingShipment = new();
    private bool isSaving;
    private string? formError;

    private bool showDeleteConfirm;
    private ShipmentDto? deletingShipment;

    private IEnumerable<ShipmentDto> FilteredShipments => string.IsNullOrWhiteSpace(filterText)
        ? shipments
        : shipments.Where(s =>
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.RecipientName.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Status.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowCreateForm()
    {
        editingShipment = new ShipmentDto { Status = "Pending", TrackingNumber = GenerateTrackingNumber() };
        formError = null;
        showForm = true;
    }

    private void EditShipment(ShipmentDto shipment)
    {
        editingShipment = new ShipmentDto
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
            CreatedAt = shipment.CreatedAt,
            EstimatedDelivery = shipment.EstimatedDelivery,
            ActualDelivery = shipment.ActualDelivery,
            RecipientName = shipment.RecipientName,
            RecipientEmail = shipment.RecipientEmail,
            Notes = shipment.Notes
        };
        formError = null;
        showForm = true;
    }

    private void CloseForm() => showForm = false;

