@page "/"
@inject IShipmentService ShipmentService

<PageTitle>Track Your Shipment - ShipmentTracker</PageTitle>

<div class="text-center mb-4">
    <h1>Shipment Tracker</h1>
    <p class="lead">Enter your tracking number to check your shipment status.</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-6">
        <div class="input-group mb-3">
            <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number..."
                   @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Track
            </button>
        </div>

        @if (result is not null)
        {
            @if (result.Found && result.Shipment is not null)
            {
                var s = result.Shipment;
                <div class="card mt-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@s.TrackingNumber</strong>
                        <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <div class="row">
                            <div class="col-6">
                                <small class="text-muted">From</small>
                                <p class="mb-1">@s.Origin</p>
                            </div>
                            <div class="col-6">
                                <small class="text-muted">To</small>
                                <p class="mb-1">@s.Destination</p>
                            </div>
                        </div>
                        <div class="row mt-2">
                            <div class="col-6">
                                <small class="text-muted">Recipient</small>
                                <p class="mb-1">@s.RecipientName</p>
                            </div>
                            <div class="col-6">
                                <small class="text-muted">Estimated Delivery</small>
                                <p class="mb-1">@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</p>
                            </div>
                        </div>
                        @if (s.ActualDelivery.HasValue)
                        {
                            <div class="row mt-2">
                                <div class="col-6">
                                    <small class="text-muted">Delivered On</small>
                                    <p class="mb-1">@s.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
                                </div>
                            </div>
                        }
                        @if (!string.IsNullOrEmpty(s.Notes))
                        {
                            <div class="mt-2">
                                <small class="text-muted">Notes</small>
                                <p class="mb-0">@s.Notes</p>
                            </div>
                        }
                    </div>
                </div>
            }
            else
            {
                <div class="alert alert-warning mt-3">
                    <strong>Not found.</strong> @result.ErrorMessage
                </div>
            }
        }
    </div>
</div>

@code {
    private string trackingNumber = string.Empty;
    private TrackingResult? result;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        result = null;
        try
        {
            result = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-info",
        "PickedUp" => "bg-secondary",
        "Exception" => "bg-danger",
        _ => "bg-warning text-dark"
    };
}

