```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
        => await http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
        => await http.GetFromJsonAsync<ShipmentDto>($"api/shipments/{id}");

    public async Task<TrackingResult> TrackShipmentAsync(string trackingNumber)
        => await http.GetFromJsonAsync<TrackingResult>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}") ?? new TrackingResult { Found = false, ErrorMessage = "Service unavailable" };

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var response = await http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDto>() ?? shipment;
    }

    public async Task<ShipmentDto> UpdateShipmentAsync(ShipmentDto shipment)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{shipment.Id}", shipment);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDto>() ?? shipment;
    }

    public async Task DeleteShipmentAsync(int id)
    {
        var response = await http.DeleteAsync($"api/shipments/{id}");
        response.EnsureSuccessStatusCode();
    }
}
```

### 5. Server-side implementation — Server project

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
        => await db.Shipments.OrderByDescending(s => s.CreatedAt).Select(s => ToDto(s)).ToListAsync();

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        var s = await db.Shipments.FindAsync(id);
        return s is null ? null : ToDto(s);
    }

    public async Task<TrackingResult> TrackShipmentAsync(string trackingNumber)
    {
        var s = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        if (s is null)
            return new TrackingResult { Found = false, ErrorMessage = "No shipment found with that tracking number." };
        return new TrackingResult { Found = true, Shipment = ToDto(s) };
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var shipment = new Shipment
        {
            TrackingNumber = dto.TrackingNumber,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = Enum.Parse<ShipmentStatus>(dto.Status),
            CreatedAt = DateTime.UtcNow,
            EstimatedDelivery = dto.EstimatedDelivery,
            RecipientName = dto.RecipientName,
            RecipientEmail = dto.RecipientEmail,
            Notes = dto.Notes
        };
        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task<ShipmentDto> UpdateShipmentAsync(ShipmentDto dto)
    {
        var shipment = await db.Shipments.FindAsync(dto.Id) ?? throw new KeyNotFoundException($"Shipment {dto.Id} not found");
        shipment.Origin = dto.Origin;
        shipment.Destination = dto.Destination;
        shipment.Status = Enum.Parse<ShipmentStatus>(dto.Status);
        shipment.EstimatedDelivery = dto.EstimatedDelivery;
        shipment.ActualDelivery = dto.ActualDelivery;
        shipment.RecipientName = dto.RecipientName;
        shipment.RecipientEmail = dto.RecipientEmail;
        shipment.Notes = dto.Notes;
        await db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task DeleteShipmentAsync(int id)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is not null)
        {
            db.Shipments.Remove(shipment);
            await db.SaveChangesAsync();
        }
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        RecipientName = s.RecipientName,
        RecipientEmail = s.RecipientEmail,
        Notes = s.Notes
    };
}
```

